def check(call, data, today):
    # Only relevant for tagging customers
    if call.get("tool") != "helpcrunch_tag_customer":
        return []
    cust_id = call.get("args", {}).get("customer_id")
    if not cust_id:
        return []

    # Get onboarding policy rows for "Recently onboarded"
    policy_rows = [r for r in records(data, tool="google_sheets_find_many_rows")
                   if r.get("worksheet_id") == "ws_onboarding_policy" and norm(r.get("Policy", "")) == "recently onboarded"]
    if not policy_rows:
        return []  # no relevant policy found

    # Find all HelpCrunch customer records for this ID
    hc_records = [r for r in records(data, tool="helpcrunch_list_customers") if r.get("id") == cust_id]
    if not hc_records:
        return []  # missing customer data

    # Determine earliest event date (created_at or any event record)
    earliest = None
    for rec in hc_records:
        dt = date(rec.get("created_at", ""))
        if dt is not None:
            if earliest is None or dt < earliest:
                earliest = dt
    if earliest is None:
        return []  # no date info

    # Parse today
    today_dt = date(today)
    if today_dt is None:
        return []

    # Apply the onboarding exclusion: within 7 days of earliest event
    if (today_dt - earliest).days <= 7:
        return [f"Customer {cust_id} is recently onboarded; tagging excluded"]
    return []

def check(call, data, today):
    # Only handle helpcrunch_tag_customer calls
    if call.get("tool") != "helpcrunch_tag_customer":
        return []
    args = call.get("args", {})
    cust_id = args.get("customer_id")
    tag = args.get("tag", "").lower()
    if not cust_id or not tag:
        return []

    # Helper to fetch all records from a specific tool
    def get_records(tool_name=None):
        return records(data, tool=tool_name) if tool_name else records(data)

    # 1. Find the threshold row for "standard" customers
    thresh_rows = [r for r in get_records("google_sheets_find_many_rows")
                   if r.get("worksheet_id") == "ws_thresholds"]
    std_row = None
    for r in thresh_rows:
        if norm(r.get("Customer Type", "")) == "standard":
            std_row = r
            break
    if not std_row:
        # No threshold info – cannot decide
        return []
    low_max = num(std_row.get("Low Max"))
    normal_max = num(std_row.get("Normal Max"))
    if low_max is None or normal_max is None:
        return []
    high_min = int(normal_max) + 1  # high usage starts just above normal max

    # 2. Determine usage count for the customer
    # Look for feature_use events in helpcrunch_list_customers records
    usage_events = [r for r in get_records("helpcrunch_list_customers")
                    if r.get("id") == cust_id and r.get("event_name") == "feature_use"]
    if not usage_events:
        # No usage data – cannot evaluate compliance
        return []
    usage_count = len(usage_events)

    # 3. Validate the tag against the usage count
    reasons = []
    if tag == "high-usage":
        if usage_count < high_min:
            reasons.append(f"Customer {cust_id} tagged high-usage but usage {usage_count}< {high_min}")
    elif tag == "normal-usage":
        if not (int(low_max) < usage_count <= int(normal_max)):
            reasons.append(f"Customer {cust_id} tagged normal-usage but usage {usage_count} not in ({int(low_max)+1}-{int(normal_max)})")
    elif tag == "low-usage":
        if usage_count > int(low_max):
            reasons.append(f"Customer {cust_id} tagged low-usage but usage {usage_count}> {int(low_max)}")
    # If tag is something else, the policy does not apply to it
    return reasons

def check(call, data, today):
    # Only relevant for email alerts
    if call.get("tool") != "gmail_send_email":
        return []
    to_addr = call.get("args", {}).get("to", "").strip().lower()
    if not to_addr:
        return []
    # Find matching customer records
    customers = [r for r in records(data, "helpcrunch_list_customers") if r.get("email", "").strip().lower() == to_addr]
    if not customers:
        return []  # no customer info, cannot decide
    # Load onboarding policy rows
    policy_rows = [r for r in records(data, "google_sheets_find_many_rows") if r.get("worksheet_id") == "ws_onboarding_policy"]
    if not policy_rows:
        return []  # policy not loaded
    # Find the rule that excludes alerts for recently onboarded customers
    exclude_rule = None
    for r in policy_rows:
        if norm(r.get("Policy", "")) == "recently onboarded" and "exclude" in norm(r.get("Action", "")):
            exclude_rule = r
            break
    if not exclude_rule:
        return []
    # Determine if any matched customer is within 7 days of their earliest event (or creation if no events)
    reasons = []
    today_date = date(today)
    for cust in customers:
        # earliest timestamp we can find: either created_at of the customer or earliest event linked to them
        earliest = date(cust.get("created_at"))
        # look for event records for this customer (same email)
        events = [e for e in records(data, "helpcrunch_list_customers") if e.get("email", "").strip().lower() == to_addr and e.get("event_name")]
        for ev in events:
            ev_date = date(ev.get("created_at"))
            if ev_date and (earliest is None or ev_date < earliest):
                earliest = ev_date
        if earliest and (today_date - earliest).days <= 7:
            reasons.append(f"{cust.get('id','customer')} is recently onboarded; email alert excluded")
    return reasons

def check(call, data, today):
    # Helper to get all records, optionally filtered by tool name
    def all_records(tool_name=None):
        recs = []
        for entry in data:
            if tool_name is None or entry.get('tool') == tool_name:
                recs.extend(entry.get('records', []))
        return recs

    # 1. Identify the customer the email is about (match by email address)
    to_addr = call.get('args', {}).get('to', '').strip().lower()
    if not to_addr:
        return []
    customer = None
    for rec in all_records('helpcrunch_list_customers'):
        email = rec.get('email', '').strip().lower()
        if email == to_addr:
            customer = rec
            break
    # If we cannot locate the customer record, we cannot decide
    if customer is None:
        return []

    # 2. Check if the customer is tagged "trial"
    tags = customer.get('tags', [])
    if isinstance(tags, str):
        # sometimes tags are stored as a comma‑separated string
        tags = [t.strip() for t in tags.split(',') if t.strip()]
    trial_tag = any(norm(t) == 'trial' for t in tags)
    if not trial_tag:
        return []  # policy does not apply to non‑trial customers

    # 3. Determine the earliest event date for the customer
    #   We use the earliest created_at among all records that share the same customer id
    cust_id = customer.get('id')
    earliest = None
    for rec in all_records('helpcrunch_list_customers'):
        if rec.get('id') != cust_id:
            continue
        d = date(rec.get('created_at'))
        if d is None:
            continue
        if earliest is None or d < earliest:
            earliest = d
    if earliest is None:
        return []  # missing date information

    # 4. Compare earliest date with today (90‑day rule)
    today_dt = date(today)
    if today_dt is None:
        return []
    if (today_dt - earliest).days <= 90:
        return []  # still within 90‑day window, policy not required

    # 5. At this point the policy requires *standard* thresholds
    body = call.get('args', {}).get('body', '')
    if not body:
        return []

    # 5a. Verify the email explicitly mentions "standard" thresholds
    if not mentions(body, 'standard'):
        return [f"Customer {customer.get('name') or to_addr} uses non‑standard thresholds"]

    # 5b. (optional) Verify the numeric values match the standard row in the thresholds sheet
    # Retrieve the standard threshold row
    std_row = None
    for rec in all_records('google_sheets_find_many_rows'):
        if rec.get('worksheet_id') != 'ws_thresholds':
            continue
        if norm(rec.get('Customer Type', '')) == 'standard':
            std_row = rec
            break
    if std_row:
        # extract numbers from the email body
        low_match = re.search(r'Low Max\s*=\s*([\d.,]+)', body, re.IGNORECASE)
        norm_match = re.search(r'Normal Max\s*=\s*([\d.,]+)', body, re.IGNORECASE)
        low_val = num(low_match.group(1)) if low_match else None
        norm_val = num(norm_match.group(1)) if norm_match else None
        std_low = num(std_row.get('Low Max'))
        std_norm = num(std_row.get('Normal Max'))
        if low_val is not None and std_low is not None and low_val != std_low:
            return [f"Customer {customer.get('name') or to_addr} low threshold {low_val} differs from standard {std_low}"]
        if norm_val is not None and std_norm is not None and norm_val != std_norm:
            return [f"Customer {customer.get('name') or to_addr} normal threshold {norm_val} differs from standard {std_norm}"]

    # No violations detected
    return []

def check(call, data, today):
    # Helper to get all records from a specific tool (or all tools if None)
    def all_records(tool=None):
        return records(data, tool)

    # Only handle salesforce_task_create calls
    if call.get("tool") != "salesforce_task_create":
        return []

    args = call.get("args", {})
    subject = args.get("subject", "")
    description = args.get("description", "")

    # Extract customer name from subject (after the first colon)
    name = ""
    if ":" in subject:
        name = subject.split(":", 1)[1].strip()
    else:
        name = subject.strip()
    if not name:
        return []

    # Find the HelpCrunch customer record matching this name (case‑insensitive)
    cust_rec = None
    for rec in all_records("helpcrunch_list_customers"):
        rec_name = rec.get("name") or rec.get("company") or ""
        if norm(rec_name) == norm(name):
            cust_rec = rec
            break
    if not cust_rec:
        return []  # no customer data → cannot evaluate

    # Check for 'trial' tag
    tags = cust_rec.get("tags", [])
    if not any(norm(t) == "trial" for t in tags):
        return []  # not a trial customer → policy not relevant

    # Determine earliest event date for this customer (any event record with same id or email)
    cust_id = cust_rec.get("id")
    cust_email = cust_rec.get("email", "").lower()
    earliest = None
    for rec in all_records("helpcrunch_list_customers"):
        # consider only event records (they have an event_name field)
        if not rec.get("event_name"):
            continue
        # match by id or email
        if rec.get("id") == cust_id or norm(rec.get("email", "")) == norm(cust_email):
            ev_date = date(rec.get("created_at"))
            if ev_date:
                if earliest is None or ev_date < earliest:
                    earliest = ev_date
    if earliest is None:
        return []  # no events → cannot decide

    # Compare earliest event to today (>90 days?)
    today_date = date(today)
    if not today_date:
        return []
    days_diff = (today_date - earliest).days
    if days_diff <= 90:
        return []  # not older than 90 days → policy not triggered

    # Parse thresholds used in the task description
    low_used = None
    normal_used = None
    for part in description.splitlines():
        if "Low Max" in part:
            try:
                low_used = int(part.split("Low Max=")[1].split(',')[0].strip())
            except Exception:
                pass
        if "Normal Max" in part:
            try:
                normal_used = int(part.split("Normal Max=")[1].split('.')[0].strip())
            except Exception:
                pass
    if low_used is None or normal_used is None:
        return []  # cannot read thresholds → no violation reported

    # Get trial thresholds from ws_thresholds sheet
    trial_row = None
    for rec in all_records("google_sheets_find_many_rows"):
        if rec.get("worksheet_id") == "ws_thresholds" and norm(rec.get("Customer Type", "")) == "trial":
            trial_row = rec
            break
    if not trial_row:
        return []  # no trial thresholds defined → cannot evaluate

    low_trial = int(trial_row.get("Low Max", "0"))
    normal_trial = int(trial_row.get("Normal Max", "0"))

    # If the used thresholds match the trial thresholds, that's a violation
    if low_used == low_trial and normal_used == normal_trial:
        return [f"{name} (trial, earliest event {earliest}) uses trial thresholds Low Max={low_used}, Normal Max={normal_used}"]

    # Otherwise, no violation
    return []

def check(call, data, today):
    # Only apply to zendesk_add_tags_to_ticket actions on tickets
    if call.get('tool') != 'zendesk_add_tags_to_ticket':
        return []
    args = call.get('args', {})
    ticket_id = args.get('ticket_id')
    if not ticket_id:
        return []
    # Gather all Zendesk ticket records
    tickets = records(data, tool='zendesk_get_tickets')
    # Find the ticket we are acting on
    target = None
    for rec in tickets:
        if rec.get('id') == ticket_id:
            target = rec
            break
    if not target:
        return []  # cannot decide without the ticket record
    # Check priority condition
    priority = norm(str(target.get('priority') or ''))
    if priority in ('high', 'urgent'):
        org = target.get('organization_id')
        if not org:
            # Violation: required organization_id missing
            return [f"Ticket {ticket_id} priority {priority} but organization_id missing"]
    return []
